def get_optional_session(x_session_id: Optional[str] = Header(default=None)) -> dict | None:
    """Extract session from header if present. Returns None for public access."""
    if not x_session_id:
        return None
    session = get_session(x_session_id)
    return session

def require_admin(x_session_id: str = Header(...)) -> dict:
    """Require a valid admin session. Raises 401/403 if not admin."""
    session = get_session(x_session_id)
    if session is None:
        raise HTTPException(status_code=401, detail="Not authenticated")
    if not session.get("is_admin"):
        raise HTTPException(status_code=403, detail="Admin access required")
    return session

def verify_token(req: TokenVerifyRequest):
    """Verify a Firebase ID token and create a session if admin."""
    try:
        claims = verify_firebase_token(req.id_token)
    except ValueError as e:
        raise HTTPException(status_code=401, detail=str(e))

    email = claims.get("email", "")
    uid = claims.get("sub", "")
    name = claims.get("name", "")
    picture = claims.get("picture", "")

    if not is_admin(email):
        logger.warning("Non-admin login attempt from %s", email)
        return {"error": f"Access denied. Only the admin can log in.", "session_id": None}

    session_id = create_session(email, uid, name, picture)
    return {
        "session_id": session_id,
        "email": email,
        "display_name": name,
        "photo_url": picture,
        "is_admin": True,
    }

def get_me(x_session_id: str = Header(...)):
    """Get current user info from session."""
    session = get_session(x_session_id)
    if session is None:
        raise HTTPException(status_code=401, detail="Session expired or invalid")
    return session

def logout(x_session_id: str = Header(...)):
