def query_rag(req: QueryRequest, session: dict | None = Depends(get_optional_session)):
    """Run the RAG pipeline. Admin gets full response; public gets answer only."""
    is_admin_user = session is not None and session.get("is_admin", False)
    cached = False
    cached_results = None

    # Check cache
    if state.cache:
        cached_results = state.cache.get(req.query, req.top_k, req.top_n, req.min_score)
        if cached_results is not None:
            cached = True

    # Run pipeline
    result = ragPipeline(
        query=req.query,
        hybrid_search=state.hybrid_search,
        reranker=state.reranker,
        llm=state.llm,
        top_k=req.top_k,
        top_n=req.top_n,
        min_score=req.min_score,
        cached_results=cached_results,
        include_chunks=is_admin_user,
    )

    # Store retrieval results in cache on miss
    if not cached and state.cache and result.get("retrieval_results"):
        try:
            state.cache.set(req.query, req.top_k, req.top_n, req.min_score, result["retrieval_results"])
        except Exception as e:
            logger.warning("Failed to cache retrieval results: %s", e)

    # Trim response for non-admin
    if is_admin_user:
        return {
            "answer": result["answer"],
            "sources": result["sources"],
            "confidence": result["confidence"],
            "timings": result.get("timings", {}),
            "cached": cached,
            "retrieval_chunks": result.get("retrieval_chunks", []),
        }
    else:
        return {"answer": result["answer"]}

