def get(self, query: str, top_k: int = 5, top_n: int = 3, min_score: float = 0.2) -> list[dict[str, Any]] | None:
    """Return cached retrieval results or *None* on miss / Redis down."""
    if self.client is None:
        self._misses += 1
        return None
    try:
        data = self.client.get(self._key(self._make_hash(query, top_k, top_n, min_score)))
        if data is not None:
            self._hits += 1
            logger.info("Cache HIT for query=%r", query, extra={"cache_hit": True, "query": query})
            return json.loads(data)
        self._misses += 1
        logger.info("Cache MISS for query=%r", query, extra={"cache_hit": False, "query": query})
        return None
    except (redis.ConnectionError, redis.TimeoutError) as exc:
        logger.warning("Redis read error (%s) — treating as cache miss.", exc)
        self._misses += 1
        return None

