    if self.client is None:
        return
    try:
        key = self._key(self._make_hash(query, top_k, top_n, min_score))
        self.client.setex(key, self.ttl, json.dumps(results, default=str))
        logger.info("Cached %d retrieval results for query=%r (TTL=%ds)", len(results), query, self.ttl)
