    """
    RAG Retriever for querying ChromaDB using encoded semantic query vectors.
    """
    def __init__(self, vector_store, embedding_manager):
        self.vector_store = vector_store
        self.embedding_manager = embedding_manager

    def retrieve(self, query: str, k: int = 5, score_threshold: float = 0.0) -> List[Dict[str, Any]]:
        query_vector = self.embedding_manager.generate_embeddings([query])[0]
        try:
